  "        state: carouselState,",
  "        stopIndex: carouselStopIndex,",
  "        stopCount: carouselStopIds.length,",
  "        poiId: carouselStopIndex >= 0 ? carouselStopIds[carouselStopIndex] : null,",
  "        resumeAfterMs: CAROUSEL_RESUME_AFTER_MS,",
  "      },",
  "    })",
